from collections import deque
def conn_to_seed(cells,seed):
    seen=set(); q=deque([cells[0],seed]); seen.add(cells[0])|{seed}
    cellsset=set(cells)|{seed}
    while q:
        x,y=q.popleft()
        for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
            nx,ny=x+dx,y+dy
            if (nx,ny) in cellsset and (nx,ny)!=(x,y):
                seen.add((nx,ny))
                q.append((nx,ny))
    return seen
