    for r in range(H):
        for c in range(W):
            v=A[r][c]
            if v!=1: seeds.setdefault(v,[]).append((r,c))
    out=[row[:] for row in A]
    # flood through adjacent-all-1 blocks from seed blocks, coloring whole reached component with seed color
    D=[(-1,0),(1,0),(0,-1),(0,1)]
    for col,ss in seeds.items():
        start=[b for b in blks if any(abs(r-b[0])<=1 and abs(c-b[1])<=1 for b in [b] for r,c in ss)]
        seen=set(start)
        while start:
            r,c=start.pop()
            vals={out[x][y] for x in (r,r+1) for y in (c,c+1)}
            for dr,dc in D:
                nr,nc=(r+dr,c+dc)
                if (nr,nc) not in seen and max(nr,nr+1)<H and max(nc,nc+1)<W and out[nr][nc]==1:
                    # is the candidate block fully all-1? check original A or just that current block's cells are all-1 in A... use A check
                    s2={A[nr][nc],A[nr][nc+1],A[nr+1][nc],A[nr+1][nc+1]}
                    if s2<={1}:
                        start.append((nr,nc)); seen.add((nr,nc))
            if col not in {v for v in vals}:
                pass
            # recolor only the part belonging to this block's top-left... actually simpler: recolor ALL cells of every block in the component
            out[r][c]=col; out[r][c+1]=col; out[r+1][c]=col; out[r+1][c+1]=col
            start=None
    return out
