        for j in range(W):
            cnt=Counter(int(a[r,c]) for dy in (-1,0,1) for dx in(-1,0,1) if dy or dx for r,c in [(i+dy,j+dx)] if 0<=r<H and 0<=c<W)
            tot=len(cnt) if False else sum(cnt.values())
            my=cnt[int(a[i,j])] if int(a[i,j]) in cnt else 0
            if my<=strict:
                best=max(cnt.items(), key=lambda kv:(kv[1], -kv[0]))
                candidates=[k for k,vv in cnt.items() if vv==best[1]]
                new=candidates[0] if tiebreak=='first' else max(candidates,key=lambda c:-c) if tiebreak=='neg' else candidates[0]
